"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3593],{25035:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"EnergyCannonConfig","desc":"Tuning for the train-mounted Energy Cannon (tier 2: twin coil barrels, cyan\\nplasma bolts, L and R alternate). It runs on the shared shell-turret code\\n(`ShellTurretServer`, `TrainTurret/ShellWeapon`, `BurstCannonMath`) in **heat\\nmode**: `HeatPerShot` being set replaces the magazine and reload with heat and\\noverheat (`EnergyCannonMath`), and `BlastRadius = 0` makes every bolt a direct\\nhit with no splash. All sound keys resolve through SoundManager/SoundConfig.\\nAngles in degrees unless the name says otherwise.","source":{"line":13,"path":"src/ReplicatedStorage/SharedModules/Configs/EnergyCannonConfig.luau"}}')}}]);